#include "rxt_private.h"
#include "dbg.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

static Boolean rxt_init_error (void) ;

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
Boolean rxt_init_nvfs (void)
{
  return(rxt_init_error()) ;
}

//--------------------------------------------------------------------------//

static Boolean rxt_init_error (void)
{
  static Rxt_Error cur_err ;
  UInt16 size = 0 ;
  
	if ((nvfs_rd_size(nvfs_rxt_err , &size) == NVFS_OK))
	{
	  if((size == sizeof(cur_err)) && (nvfs_rd(nvfs_rxt_err , &rxt_err) == NVFS_OK))
	  {
		  #if DBG_RXT == 1
			dbg_tx_text ("\n nvfs_rxt_err is up to date") ;
		  #endif
		  return (TRUE) ;
	  }
	}

  nvfs_delete(nvfs_rxt_err);

  rxt_err = cur_err ;

  switch (nvfs_wr_create(nvfs_rxt_err, &rxt_err , sizeof(Rxt_Error)))
    {
      case NVFS_OK :  
        {         
		   #if DBG_RXT == 1
			 dbg_tx_text ("\n nvfs_rxt_err re-created") ;
		   #endif
           return rxt_init_error() ; 
        }  
    }      
  return FALSE ;
}


